 DrawingEditorModel model;model.snapshot.version={QUuid::createUuid(),{}};model.snapshot.bodies={source(patch(.2),1)};model.choices={{1,"Raccordo circolare inclinato"}};DrawingView v;v.plane=Frame3(Vec3(),normalized(Vec3(.4,0,1)),Vec3(0,1,0));v.scale=150;std::vector<DrawingCurve> curves;ok(drawingViewCurves(model.snapshot,v,curves));require(curves.size()==1&&!drawingPrimitive(v,curves[0]).circular,"sezione obliqua non circolare del profilo");
 const auto &curve=curves[0];const double parameter=(curve.range.lo+curve.range.hi)/2;const auto profile=drawingProfileRadius(v,curve,model.snapshot,parameter);require(profile.has_value(),"raggio del profilo disponibile sulla superficie");near(profile->radius,.2,"raggio del profilo analitico");const auto reference=drawingAttachment(v,curve,model.snapshot,DrawingPointRole::Curve,parameter);const auto d=drawingDimensionBetween(v,model.snapshot,curves,{reference},DrawingMeasure::Radius,{2,2});require(d.measure==DrawingMeasure::ProfileRadius,"Raggio diventa esplicitamente R profilo sulla sezione non circolare");
 DrawingSheet sheet;sheet.drawing.model=model.snapshot.version;sheet.drawing.views={v};sheet.drawing.dimensions={d};sheet.views={{v.id,"Sezione obliqua",{75,120},{1}}};sheet.dimensions={{d.id,{130,150}}};QByteArray bytes;ok(encodeDrawingSheet(sheet,bytes));auto json=QJsonDocument::fromJson(bytes).object();require(json["schema"].toInt()==25&&json["drawing"].toObject()["schema"].toInt()==12,"schemi distinti per il raggio del profilo");DrawingSheet restored;ok(decodeDrawingSheet(bytes,restored));DrawingSheetEditor e(restored,model);near(e.dimensionResult(d.id).value,.2,"raggio profilo dopo riapertura");require(qgraphicsitem_cast<QGraphicsSimpleTextItem *>(dimensionTextItem(e,d.id))->text().startsWith("R profilo"),"quota del profilo esplicita nel testo");auto changed=model;changed.snapshot.bodies={source(patch(.3),1)};ok(e.updateModel(changed));near(e.dimensionResult(d.id).value,.3,"raggio del profilo segue il modello");
 json["schema"]=24;require(!decodeDrawingSheet(QJsonDocument(json).toJson(),restored).isEmpty(),"vecchio schema foglio rifiuta il profilo");json=QJsonDocument::fromJson(bytes).object();auto document=json["drawing"].toObject();document["schema"]=11;json["drawing"]=document;require(!decodeDrawingSheet(QJsonDocument(json).toJson(),restored).isEmpty(),"vecchio schema geometrico rifiuta il profilo");
